
USE `metroseed`;

-- Keep this seed compatible with an older applicants table.
SET @applicant_office_exists = (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'applicants' AND COLUMN_NAME = 'office_id');
SET @applicant_office_sql = IF(@applicant_office_exists = 0, 'ALTER TABLE `applicants` ADD COLUMN `office_id` VARCHAR(20) NULL AFTER `ofw_country`', 'SELECT 1');
PREPARE applicant_office_statement FROM @applicant_office_sql;
EXECUTE applicant_office_statement;
DEALLOCATE PREPARE applicant_office_statement;

